import { sendingPause } from "@/lib/sending-pause";
import "server-only";
import {
  applyFreeCampaignPolicy,
  cancelIneligibleCampaign,
} from "@/lib/campaign-policy";
import { db } from "@/lib/db";
import { historicalUsagePeriods } from "@/lib/usage-periods";
import { canUser } from "@/lib/entitlements";
import { completeCampaignIn } from "@/lib/cancellation";
import { preserveAcceptedSend } from "@/lib/usage-backfill";
import {
  markUsageUncertain,
  releaseUsage,
  repairUsageCounters,
  settleUsageReceipt,
  warnUsage,
  withUsageTransaction,
} from "@/lib/usage-ledger";

export type UsageDispatchEvent = {
  id: string;
  name: "mailloop/email.queued";
  data: { userId: string; sendId: string };
};
export type UsagePublisher = (events: UsageDispatchEvent[]) => Promise<unknown>;
const REPAIR_DELAY = 5 * 60000;

/** Commit publication metadata before network work. Every repair has a fresh
 * generation; claim state and the original delivery identity remain unchanged. */
export async function dispatchUsagePending(
  userId: string,
  publish: UsagePublisher,
  now = new Date(Date.now()),
) {
  const active = await db.user.findFirst({
    where: { id: userId, deletionRequestedAt: null },
    select: { id: true },
  });
  if (!active) return 0;
  const pending = await withUsageTransaction(db, userId, async (owner) => {
    const { tx } = owner;
    await applyFreeCampaignPolicy(owner, now);
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    const control = await tx.systemControl.findUnique({
      where: { key: "global" },
    });
    // Policy cancellation also applies to delayed READY work and while the
    // sending switch is paused. Publication eligibility is checked afterwards.
    if (control?.paidGatingEnabled) {
      const campaigns = await tx.campaign.findMany({
        where: {
          userId,
          sends: { some: { status: "QUEUED", deliveryState: "READY" } },
        },
        select: { id: true },
      });
      for (const campaign of campaigns)
        await cancelIneligibleCampaign(tx, userId, campaign.id, now);
    }
    if (
      sendingPause(user, control, now) ||
      !canUser(user, "send", control, now).allowed
    )
      return [];
    const sends = await tx.send.findMany({
      where: {
        campaign: { userId },
        status: "QUEUED",
        deliveryState: "READY",
        AND: [
          { OR: [{ availableAt: null }, { availableAt: { lte: now } }] },
          { OR: [{ queueExpiresAt: null }, { queueExpiresAt: { gt: now } }] },
          {
            OR: [
              { dispatchAttemptedAt: null },
              { dispatchAttemptedAt: { lte: new Date(+now - REPAIR_DELAY) } },
            ],
          },
        ],
      },
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
      take: 100,
    });
    const rows = [];
    for (const send of sends) {
      if (+now - +send.createdAt > REPAIR_DELAY)
        warnUsage("PUBLICATION_DELAY", userId, send.id);
      const updated = await tx.send.update({
        where: { id: send.id, campaign: { userId } },
        data: {
          dispatchGeneration: { increment: 1 },
          dispatchAttempts: { increment: 1 },
          dispatchAttemptedAt: now,
        },
      });
      rows.push({ id: send.id, generation: updated.dispatchGeneration });
    }
    return rows;
  });
  if (!pending.length) return 0;
  try {
    await publish(
      pending.map((s) => ({
        id: `send-${s.id}-${s.generation}`,
        name: "mailloop/email.queued",
        data: { userId, sendId: s.id },
      })),
    );
    for (const send of pending)
      await db.send.updateMany({
        where: {
          id: send.id,
          campaign: { userId },
          dispatchGeneration: send.generation,
        },
        data: { dispatchedAt: now },
      });
  } catch {
    warnUsage("PUBLICATION_FAILED", userId);
    throw new Error("QUEUE_PUBLICATION_FAILED");
  }
  return pending.length;
}

export async function reconcileUsageOwner(
  userId: string,
  now = new Date(Date.now()),
) {
  return withUsageTransaction(db, userId, async (owner) => {
    const { tx } = owner;
    const drift = await repairUsageCounters(owner);
    if (drift.length) warnUsage("COUNTER_DRIFT", userId);
    const sends = await tx.send.findMany({
      where: { campaign: { userId } },
      orderBy: { id: "asc" },
    });
    const campaigns = new Set<string>();
    for (const send of sends) {
      const ledger = await tx.usageReservation.findFirst({
        where: { userId, sendId: send.id },
      });
      if (
        send.sentAt &&
        (["SENT", "REPLIED"].includes(send.status) || send.gmailMessageId)
      ) {
        if (ledger && ledger.status !== "CONFIRMED") {
          await preserveAcceptedSend(owner, send.id);
          campaigns.add(send.campaignId);
        }
        continue;
      }
      if (!ledger) {
        if (
          send.status === "QUEUED" ||
          ["ATTEMPTING", "UNCERTAIN"].includes(send.deliveryState)
        )
          warnUsage("MISSING_ACCOUNTING", userId, send.id);
        continue;
      }
      if (
        ledger.status === "ATTEMPTING" &&
        ledger.leaseExpiresAt &&
        ledger.leaseExpiresAt <= now
      ) {
        await markUsageUncertain(
          owner,
          ledger.deliveryKey,
          ledger.claimToken!,
          now,
          true,
        );
        campaigns.add(send.campaignId);
      }
      if (
        ["UNCERTAIN", "ATTEMPTING"].includes(ledger.status) &&
        ledger.chargedAt &&
        +now - +ledger.chargedAt > 15 * 60000
      )
        warnUsage("UNCERTAINTY_OLDER_THAN_15_MINUTES", userId, send.id);
      const expired =
        send.status === "QUEUED" &&
        send.deliveryState === "READY" &&
        send.queueExpiresAt &&
        send.queueExpiresAt <= now;
      const terminalUnsent =
        ["FAILED", "CANCELLED"].includes(send.status) &&
        ["READY", "DONE"].includes(send.deliveryState);
      if (
        ledger.status === "RESERVED" &&
        !send.attemptedAt &&
        !send.gmailMessageId &&
        !send.sentAt &&
        (expired || terminalUnsent)
      ) {
        await releaseUsage(
          owner,
          ledger.deliveryKey,
          { kind: "UNSUBMITTED" },
          now,
        );
        if (send.status === "FAILED")
          await tx.send.updateMany({
            where: { id: send.id, campaign: { userId } },
            data: { status: "FAILED" },
          });
        campaigns.add(send.campaignId);
      }
    }
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    const receipts = await tx.deliveryReceipt.findMany({
      where: { userId, deliveryKey: { not: null } },
    });
    for (const receipt of receipts) {
      const row = await tx.usageReservation.findFirst({
        where: { userId, deliveryKey: receipt.deliveryKey! },
      });
      if (row && row.status !== "CONFIRMED")
        await settleUsageReceipt(
          owner,
          receipt.id,
          historicalUsagePeriods(user, row.chargedAt ?? receipt.sentAt),
        );
    }
    const orphans = await tx.usageReservation.findMany({
      where: {
        userId,
        sendId: null,
        status: { in: ["RESERVED", "ATTEMPTING", "UNCERTAIN"] },
      },
    });
    for (const row of orphans) {
      if (
        row.status === "ATTEMPTING" &&
        row.leaseExpiresAt &&
        row.leaseExpiresAt <= now
      )
        await markUsageUncertain(
          owner,
          row.deliveryKey,
          row.claimToken!,
          now,
          true,
        );
      if (row.chargedAt && +now - +row.chargedAt > 15 * 60000)
        warnUsage("UNCERTAINTY_OLDER_THAN_15_MINUTES", userId);
    }
    if (orphans.length) warnUsage("OUTSTANDING_ORPHAN", userId);
    await repairUsageCounters(owner);
    for (const id of campaigns) await completeCampaignIn(tx, userId, id);
    return { drift: drift.length, orphans: orphans.length };
  });
}

// System enumeration returns IDs only. Each owner transaction and publication
// is independent, so one broken account cannot stall the remaining owners.
export async function reconcileUsagePage(
  publish: UsagePublisher,
  after?: string,
  now = new Date(),
) {
  const owners = await db.user.findMany({
    where: after ? { id: { gt: after } } : {},
    select: { id: true },
    orderBy: { id: "asc" },
    take: 50,
  });
  let processed = 0,
    failed = 0;
  for (const { id } of owners) {
    try {
      await reconcileUsageOwner(id, now);
      await dispatchUsagePending(id, publish, now);
      processed++;
    } catch {
      failed++;
      warnUsage("REPAIR_FAILED", id);
    }
  }
  return {
    processed,
    failed,
    cursor: owners.length === 50 ? owners.at(-1)!.id : null,
  };
}
export async function reconcileUsageOwners(
  publish: UsagePublisher,
  now = new Date(),
) {
  let cursor: string | undefined,
    processed = 0,
    failed = 0;
  do {
    const page = await reconcileUsagePage(publish, cursor, now);
    processed += page.processed;
    failed += page.failed;
    cursor = page.cursor ?? undefined;
  } while (cursor);
  return { processed, failed };
}
